Algorithm LAGRANGIAN_HIERARCHICAL_PATCHING(problem_spec, time_limit, params, seed)
  Init hooks: ENCODE, DECODE, COST, CONSTRAINTS, RELAX_SOLVER, PATCHER, CLUSTER, PARTIAL_OPT
  x_best ← construct_greedy_seed(problem_spec, seed); best_cost ← COST(x_best); multipliers ← zero(CONSTRAINTS)
  coarse_hierarchy ← build_multilevel_coarsening(problem_spec, params.levels)
  while not stop(time_limit, improvement_tol):
    // 1. Relaxed master solve under current multipliers (continuous/LP/penalized heuristic)
    x_relaxed ← RELAX_SOLVER(problem_spec, multipliers, coarse_hierarchy.current_level, params)
    // 2. Hierarchical stitching: cluster, patch fractional/infeasible parts into a feasible candidate
    clusters ← CLUSTER(x_relaxed, problem_spec, multipliers)
    x_candidate ← PATCHER(x_relaxed, clusters, PARTIAL_OPT, problem_spec, params)
    x_candidate ← repair_if_needed(x_candidate, CONSTRAINTS)
    c ← COST(x_candidate)
    if c < best_cost and validate(x_candidate, CONSTRAINTS): x_best, best_cost ← x_candidate, c
    // 3. Compute constraint violation subgradient and update multipliers (Polyak/diminishing)
    subgrad ← compute_violations(x_candidate, CONSTRAINTS); step ← step_size_schedule(subgrad, params)
    multipliers ← max(0, multipliers + step * subgrad)
    // 4. Targeted intensive improvement on high-violation or high-impact clusters
    hotspots ← select_hotspots(subgrad, clusters, params.hotspot_threshold)
    for h in hotspots: x_candidate ← PARTIAL_OPT(x_candidate, h, problem_spec, params)
    // 5. Adaptive hierarchy control and stochastic perturbation for diversification
    if stagnation_detected(): coarse_hierarchy := descend_or_recoarsen(coarse_hierarchy); multipliers := random_perturb(multipliers, params)
  return DECODE(x_best)

